(() => {
  'use strict';
  const DATA = window.FASHIONHUB_DATA || {};
  const products = DATA.products || [];
  const categories = DATA.categories || [];
  const tree = DATA.categoryTree || [];
  const CART_KEY = 'fashionhub-demo-cart-v2';
  const WISH_KEY = 'fashionhub-demo-wishlist-v2';
  const $ = (s,r=document)=>r.querySelector(s);
  const $$ = (s,r=document)=>Array.from(r.querySelectorAll(s));
  const esc = v => String(v ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const money = n => `৳${Number(n||0).toLocaleString('en-BD')}`;
  const read = (k, fallback) => { try { const v=localStorage.getItem(k); return v ? JSON.parse(v) : fallback; } catch(_){return fallback;} };
  const write = (k,v) => { try{localStorage.setItem(k,JSON.stringify(v));}catch(_){} };
  let cart = read(CART_KEY, {});
  let wishlist = new Set(read(WISH_KEY, []));
  let quantity = 1;
  const byId = id => products.find(p=>Number(p.id)===Number(id));
  const q = name => new URLSearchParams(location.search).get(name);
  const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const stars = r => '★★★★★'.slice(0,Math.max(1,Math.round(Number(r)||5)));

  const sprite = `<svg class="svg-sprite" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">
  <symbol id="i-menu" viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16"/></symbol><symbol id="i-close" viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></symbol><symbol id="i-search" viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></symbol><symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 21c.7-4.4 3.2-7 8-7s7.3 2.6 8 7"/></symbol><symbol id="i-heart" viewBox="0 0 24 24"><path d="M20.8 5.8c-2.2-2.2-5.7-2.2-7.9 0l-.9.9-.9-.9a5.6 5.6 0 0 0-7.9 7.9l.9.9L12 22l7.9-7.4.9-.9a5.6 5.6 0 0 0 0-7.9Z"/></symbol><symbol id="i-cart" viewBox="0 0 24 24"><path d="M3 4h2l2.2 10.1a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 2-1.5L21 7H6"/><circle cx="10" cy="20" r="1"/><circle cx="18" cy="20" r="1"/></symbol><symbol id="i-bag" viewBox="0 0 24 24"><path d="M5 8h14l1 13H4L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></symbol><symbol id="i-grid" viewBox="0 0 24 24"><rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/></symbol><symbol id="i-slider" viewBox="0 0 24 24"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2"/><circle cx="15" cy="17" r="2"/></symbol><symbol id="i-chevron-down" viewBox="0 0 24 24"><path d="m7 10 5 5 5-5"/></symbol><symbol id="i-chevron-up" viewBox="0 0 24 24"><path d="m7 14 5-5 5 5"/></symbol><symbol id="i-chevron-left" viewBox="0 0 24 24"><path d="m15 5-7 7 7 7"/></symbol><symbol id="i-chevron-right" viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></symbol><symbol id="i-arrow-right" viewBox="0 0 24 24"><path d="M5 12h14M14 7l5 5-5 5"/></symbol><symbol id="i-truck" viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/></symbol><symbol id="i-return" viewBox="0 0 24 24"><path d="M9 7H5v-4M5 7a8 8 0 1 1-1 8"/></symbol><symbol id="i-shield" viewBox="0 0 24 24"><path d="M12 3 4.5 6v5.5c0 4.9 3 8.4 7.5 9.5 4.5-1.1 7.5-4.6 7.5-9.5V6L12 3Z"/><path d="m9 12 2 2 4-4"/></symbol><symbol id="i-headset" viewBox="0 0 24 24"><path d="M4 14v-2a8 8 0 0 1 16 0v2"/><path d="M4 14h3v6H5a2 2 0 0 1-2-2v-2a2 2 0 0 1 1-2ZM20 14h-3v6h2a2 2 0 0 0 2-2v-2a2 2 0 0 0-1-2ZM17 20c-1 1-2.4 1.5-4 1.5"/></symbol><symbol id="i-bolt" viewBox="0 0 24 24"><path d="m13 2-8 12h7l-1 8 8-12h-7l1-8Z"/></symbol><symbol id="i-check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol><symbol id="i-ticket" viewBox="0 0 24 24"><path d="M4 6h16v4a2 2 0 0 0 0 4v4H4v-4a2 2 0 0 0 0-4V6Z"/><path d="M13 8 9 16"/></symbol><symbol id="i-gift" viewBox="0 0 24 24"><path d="M3 10h18v11H3zM2 7h20v3H2zM12 7v14"/><path d="M12 7c-1-4-6-4-6-1 0 2 3 2 6 1Zm0 0c1-4 6-4 6-1 0 2-3 2-6 1Z"/></symbol><symbol id="i-wallet" viewBox="0 0 24 24"><path d="M3 6a2 2 0 0 1 2-2h13v4H5a2 2 0 0 0 0 4h16v8H5a2 2 0 0 1-2-2V6Z"/><circle cx="17" cy="14" r="1"/></symbol><symbol id="i-box" viewBox="0 0 24 24"><path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="m4 7 8 4v10l-8-4V7Zm16 0-8 4v10l8-4V7Z"/></symbol><symbol id="i-star" viewBox="0 0 24 24"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></symbol><symbol id="i-phone" viewBox="0 0 24 24"><rect x="7" y="2" width="10" height="20" rx="2"/><path d="M10 5h4M11 19h2"/></symbol><symbol id="i-mail" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></symbol><symbol id="i-location" viewBox="0 0 24 24"><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></symbol><symbol id="i-eye" viewBox="0 0 24 24"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></symbol><symbol id="i-plus" viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></symbol><symbol id="i-minus" viewBox="0 0 24 24"><path d="M5 12h14"/></symbol></svg>`;

  function menuItems(){ return [
    ['Home','index.html'],['Shop','shop.html'],['New Arrivals','shop.html?sort=new'],['Women','category.html?cat=women'],['Men','category.html?cat=men'],['Digital','category.html?cat=digital'],['Deals','archive.html?type=deals'],['Blog','blog.html'],['Contact','contact.html']
  ];}
  function nestedTree(items, depth=0){
    return `<ul class="${depth ? '' : 'mobile-tree'}">${items.map((item,i)=>`<li><div class="mobile-tree__row"><a href="${item.url || (depth ? `category.html?cat=${encodeURIComponent((item.label||'').toLowerCase().replace(/\s+/g,'-'))}` : '#')}">${esc(item.label)}</a>${item.children?.length?`<button type="button" data-action="submenu" aria-expanded="false" aria-label="Open ${esc(item.label)}">${icon('chevron-down')}</button>`:''}</div>${item.children?.length?nestedTree(item.children,depth+1):''}</li>`).join('')}</ul>`;
  }
  function desktopCategoryTree(){
    return `<div class="category-mega__list">${tree.map((item,i)=>`<button type="button" class="category-mega__item${i===0?' is-active':''}" data-cat-index="${i}"><span>${icon(item.icon||'grid')}${esc(item.label)}</span>${icon('chevron-right')}</button>`).join('')}</div><div class="category-mega__details" id="categoryMegaDetails"></div>`;
  }
  function catDetails(index=0){
    const item=tree[index]||tree[0]; if(!item) return '';
    return `<div class="category-mega__heading"><span>${esc(item.label)}</span><a href="category.html?cat=${encodeURIComponent(item.label.toLowerCase().replace(/\s+/g,'-'))}">View all ${icon('arrow-right')}</a></div><div class="category-mega__columns">${(item.children||[]).map(child=>`<section><h3>${esc(child.label)}</h3>${(child.children||[]).map(grand=>`<a href="category.html?cat=${encodeURIComponent(grand.label.toLowerCase().replace(/\s+/g,'-'))}">${esc(grand.label)}</a>`).join('')}</section>`).join('')}</div>`;
  }
  function header(){
    return `<a class="skip-link" href="#main-content">Skip to content</a><div class="announcement"><div class="shell announcement__inner"><div class="announcement__items"><span>${icon('truck')} Free delivery over ৳3,000</span><span>${icon('return')} 7-day easy return</span><span>${icon('shield')} Secure payment</span></div><div class="announcement__right"><a href="tel:+8801234567890">Need help? +880 1234 567890</a><button type="button" class="language-switch">English ${icon('chevron-down')}</button></div></div></div>
    <header class="site-header"><div class="shell header-main"><button class="icon-button menu-trigger" type="button" data-action="open-menu" aria-label="Open navigation">${icon('menu')}</button><a class="brand" href="index.html"><span class="brand__mark">${icon('bag')}</span><span>Fashion<span>Hub</span></span></a><div class="category-launcher desktop-only"><button class="category-launcher__button" type="button" data-action="toggle-categories" aria-expanded="false">${icon('grid')}<span>All Categories</span>${icon('chevron-down')}</button><nav class="category-mega" id="desktopCategoryMenu">${desktopCategoryTree()}</nav></div><form class="site-search" id="pageSiteSearch"><input id="pageSearchInput" type="search" placeholder="Search products, categories or digital files…"><button type="submit">${icon('search')}</button><div class="search-results" id="pageSearchResults" hidden></div></form><nav class="header-actions"><button class="header-action search-mobile-trigger" type="button" data-action="focus-search">${icon('search')}<span>Search</span></button><a class="header-action" href="account.html">${icon('user')}<span>Account</span></a><a class="header-action" href="wishlist.html"><span class="action-icon">${icon('heart')}<b class="count-badge" id="wishlistCount">0</b></span><span>Wishlist</span></a><button class="header-action" type="button" data-action="open-cart"><span class="action-icon">${icon('cart')}<b class="count-badge" id="cartCount">0</b></span><span>Cart</span></button></nav></div><div class="primary-nav-wrap desktop-only"><nav class="shell primary-nav">${menuItems().map(([l,u])=>`<a href="${u}">${esc(l)}</a>`).join('')}</nav></div></header>`;
  }
  function footer(){
    return `<section class="newsletter"><div class="shell newsletter__inner"><div class="newsletter__copy"><span class="newsletter__icon">${icon('mail')}</span><div><h2>Subscribe to Our Newsletter</h2><p>Get new arrivals, exclusive offers and coupon alerts.</p></div></div><form id="pageNewsletter"><input type="email" required placeholder="Enter your email address"><button type="submit">Subscribe</button></form></div></section><footer class="site-footer"><div class="shell footer-grid"><section class="footer-about"><a class="brand brand--footer" href="index.html"><span class="brand__mark">${icon('bag')}</span><span>Fashion<span>Hub</span></span></a><p>A fast multi-category store template for physical products, digital downloads, offers and coupon campaigns.</p><div class="social-links"><a href="#">f</a><a href="#">◎</a><a href="#">▶</a><a href="#">in</a></div></section><section><h2>Shop</h2><a href="category.html?cat=women">Women</a><a href="category.html?cat=men">Men</a><a href="category.html?cat=electronics">Electronics</a><a href="category.html?cat=home">Home & Living</a><a href="category.html?cat=digital">Digital Products</a><a href="shop.html">All Categories</a></section><section><h2>Customer Service</h2><a href="contact.html">Contact Us</a><a href="contact.html">Help Center</a><a href="checkout.html">Shipping Policy</a><a href="contact.html">Return & Refund</a><a href="account.html">Track Order</a><a href="category.html?cat=digital">Download Help</a></section><section><h2>Information</h2><a href="contact.html">About Us</a><a href="#">Terms & Conditions</a><a href="#">Privacy Policy</a><a href="archive.html?type=deals">Coupon Policy</a><a href="blog.html">Blog</a><a href="shop.html">Sitemap</a></section><section class="footer-contact"><h2>Contact Us</h2><p>${icon('phone')}<span>+880 1234 567890</span></p><p>${icon('mail')}<span>support@fashionhub.com</span></p><p>${icon('location')}<span>Dhaka, Bangladesh</span></p><div class="payment-badges"><span>VISA</span><span>Mastercard</span><span>bKash</span><span>Nagad</span></div></section></div><div class="shell footer-bottom"><span>© 2026 FashionHub. All rights reserved.</span><div><a href="#">Privacy</a><a href="#">Terms</a><a href="#">Cookies</a></div></div></footer>`;
  }
  function overlays(){
    return `<div class="filter-backdrop" id="filterBackdrop" data-action="close-filters"></div><div class="drawer-backdrop" id="drawerBackdrop" data-action="close-menu"></div><aside class="mobile-drawer" id="mobileDrawer"><div class="drawer-header"><a class="brand" href="index.html"><span class="brand__mark">${icon('bag')}</span><span>Fashion<span>Hub</span></span></a><button class="icon-button" data-action="close-menu">${icon('close')}</button></div><div class="drawer-tabs"><button class="is-active" data-drawer-tab="menu">Menu</button><button data-drawer-tab="categories">Categories</button></div><div class="drawer-content"><nav class="drawer-panel is-active" data-drawer-panel="menu">${nestedTree(menuItems().map(([label,url])=>({label,url})))}</nav><nav class="drawer-panel" data-drawer-panel="categories">${nestedTree(tree)}</nav></div><div class="drawer-support">${icon('headset')}<div><b>Need help?</b><a href="tel:+8801234567890">+880 1234 567890</a></div></div></aside><div class="cart-backdrop" id="cartBackdrop" data-action="close-cart"></div><aside class="cart-drawer" id="cartDrawer"><div class="cart-drawer__header"><div><h2>Your Cart</h2><span id="cartSummary">0 items</span></div><button class="icon-button" data-action="close-cart">${icon('close')}</button></div><div class="cart-items" id="cartItems"></div><div class="cart-drawer__footer"><div><span>Subtotal</span><b id="cartSubtotal">৳0</b></div><a class="primary-button primary-button--full" href="checkout.html">Proceed to Checkout</a><a class="secondary-button secondary-button--full" href="cart.html">View Cart</a></div></aside><div class="toast-region" id="toastRegion" aria-live="polite"></div><button class="back-to-top" data-action="back-to-top">${icon('chevron-up')}</button>`;
  }
  function installChrome(){
    document.body.insertAdjacentHTML('afterbegin', sprite + header());
    document.body.insertAdjacentHTML('beforeend', footer()+overlays());
    const d=$('#categoryMegaDetails'); if(d) d.innerHTML=catDetails(0);
    updateCounts(); renderDrawerCart();
  }
  function breadcrumb(items){ return `<nav class="page-crumbs" aria-label="Breadcrumb"><a href="index.html">Home</a>${items.map((x,i)=>`${icon('chevron-right')}${i===items.length-1?`<span>${esc(x.label)}</span>`:`<a href="${x.url||'#'}">${esc(x.label)}</a>`}`).join('')}</nav>`; }
  function badgeClass(p){return p.type==='digital'?' product-badge--digital':String(p.badge).toLowerCase()==='new'?' product-badge--new':'';}
  function productCard(p){ if(!p) return ''; return `<article class="product-card"><a class="product-card__media" href="product.html?id=${p.id}"><span class="product-badge${badgeClass(p)}">${esc(p.badge||'New')}</span><img src="${esc(p.image)}" width="420" height="420" loading="lazy" alt="${esc(p.name)}"></a><button class="product-card__wish${wishlist.has(p.id)?' is-active':''}" type="button" data-action="toggle-wishlist" data-product-id="${p.id}">${icon('heart')}</button><div class="product-card__body"><span class="product-card__category">${esc(p.category)} · ${esc(p.type)}</span><h3><a href="product.html?id=${p.id}">${esc(p.name)}</a></h3><div class="product-card__rating"><span>${stars(p.rating)}</span><small>${p.rating} (${p.reviews})</small></div><div class="product-card__footer"><div class="product-price"><strong>${money(p.price)}</strong><del>${money(p.oldPrice)}</del></div><button class="add-button" data-action="add-cart" data-product-id="${p.id}">${icon('plus')}</button></div></div></article>`; }
  function filterPanel(){
    const depts=[...new Set(products.map(p=>p.department))]; const cats=[...new Set(products.map(p=>p.category))].slice(0,12);
    return `<aside class="filter-panel" id="filterPanel"><div class="filter-head"><h2>Filters</h2><div><button class="filter-reset" data-action="reset-filters">Reset all</button><button class="filter-close" data-action="close-filters" aria-label="Close filters">${icon('close')}</button></div></div><div class="filter-group"><h3>Department</h3><div class="filter-list">${depts.map(d=>`<div class="filter-check"><label><input type="checkbox" data-filter="department" value="${esc(d)}"> ${esc(d)}</label><small>${products.filter(p=>p.department===d).length}</small></div>`).join('')}</div></div><div class="filter-group"><h3>Category</h3><div class="filter-list">${cats.map(c=>`<div class="filter-check"><label><input type="checkbox" data-filter="category" value="${esc(c)}"> ${esc(c)}</label><small>${products.filter(p=>p.category===c).length}</small></div>`).join('')}</div></div><div class="filter-group"><h3>Product type</h3><div class="filter-list"><div class="filter-check"><label><input type="checkbox" data-filter="type" value="physical"> Physical products</label></div><div class="filter-check"><label><input type="checkbox" data-filter="type" value="digital"> Digital downloads</label></div></div></div><div class="filter-group"><h3>Price range</h3><div class="price-fields"><input id="priceMin" type="number" min="0" placeholder="Min"><input id="priceMax" type="number" min="0" placeholder="Max"></div><button class="filter-apply" type="button" data-action="apply-filters">Apply price</button></div></aside>`;
  }
  function toolbar(count){return `<div class="catalog-toolbar"><div class="catalog-toolbar__left"><button class="mobile-filter-btn" data-action="open-filters">${icon('slider')} Filters</button><span>Showing <b id="resultCount">${count}</b> products</span></div><div class="catalog-toolbar__right"><select id="sortSelect" aria-label="Sort products"><option value="featured">Featured</option><option value="new">Newest</option><option value="price-low">Price: Low to High</option><option value="price-high">Price: High to Low</option><option value="rating">Top Rated</option></select><div class="catalog-view"><button class="is-active" data-action="grid-view">${icon('grid')}</button><button data-action="list-view">${icon('menu')}</button></div></div></div>`;}
  let catalogBase=[];
  function renderCatalog(list){ catalogBase=list.slice(); const grid=$('#catalogGrid'); if(grid) grid.innerHTML=list.map(productCard).join(''); const c=$('#resultCount'); if(c)c.textContent=list.length; }
  function applyCatalog(){
    let list=catalogBase.slice(); const selected={department:[],category:[],type:[]}; $$('[data-filter]:checked').forEach(i=>selected[i.dataset.filter].push(i.value));
    Object.entries(selected).forEach(([k,vals])=>{ if(vals.length) list=list.filter(p=>vals.includes(p[k])); });
    const min=Number($('#priceMin')?.value||0), max=Number($('#priceMax')?.value||0); if(min)list=list.filter(p=>p.price>=min); if(max)list=list.filter(p=>p.price<=max);
    const sort=$('#sortSelect')?.value||'featured'; if(sort==='price-low')list.sort((a,b)=>a.price-b.price); if(sort==='price-high')list.sort((a,b)=>b.price-a.price); if(sort==='rating')list.sort((a,b)=>b.rating-a.rating); if(sort==='new')list.sort((a,b)=>b.id-a.id);
    const grid=$('#catalogGrid'); if(grid) grid.innerHTML=list.map(productCard).join(''); const c=$('#resultCount'); if(c)c.textContent=list.length;
  }
  function shopPage(){ const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Shop'}])}<div class="page-titlebar"><div><h1>Shop All Products</h1><p>Explore fashion, electronics, beauty, lifestyle products and instant digital downloads in one fast catalog.</p></div><div class="page-titlebar__meta"><span class="soft-pill">${icon('shield')} Secure checkout</span><span class="soft-pill">${icon('return')} Easy returns</span></div></div><div class="subcat-chips">${categories.map(c=>`<a href="category.html?cat=${c.id}"><img src="${c.image}" width="26" height="26" alt="">${esc(c.name)}</a>`).join('')}</div><div class="catalog-layout">${filterPanel()}<section class="catalog-content">${toolbar(products.length)}<div class="catalog-grid" id="catalogGrid"></div><nav class="pagination"><a class="is-active" href="#">1</a><a href="#">2</a><a href="#">3</a><a href="#">4</a><a href="#">${icon('chevron-right')}</a></nav></section></div></div>`; renderCatalog(products); }
  function categoryPage(){
    const slug=(q('cat')||'women').toLowerCase(); const cat=categories.find(c=>c.id===slug)||categories.find(c=>c.name.toLowerCase().replace(/\s+/g,'-')===slug)||categories[0]; let list=products.filter(p=>p.category.toLowerCase().includes(cat.name.toLowerCase().split(' ')[0])||p.department.toLowerCase().includes(cat.name.toLowerCase().split(' ')[0])); if(!list.length){if(slug==='digital')list=products.filter(p=>p.type==='digital'); else if(slug==='electronics')list=products.filter(p=>p.department==='Electronics'); else list=products.slice(0,16);} const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Shop',url:'shop.html'},{label:cat.name}])}<section class="page-banner"><div><span class="eyebrow">${list.length} products</span><h1>${esc(cat.name)}</h1><p>Curated products, clear pricing and quick delivery options from our ${esc(cat.name.toLowerCase())} collection.</p><a class="primary-button" href="#categoryProducts">Shop collection ${icon('arrow-right')}</a></div><img src="${cat.image}" alt="${esc(cat.name)}"></section><div class="subcat-chips"><a class="is-active" href="#">All ${esc(cat.name)}</a><a href="#">Best Sellers</a><a href="#">New Arrivals</a><a href="#">Under ৳2,000</a><a href="#">Top Rated</a><a href="#">Offers</a></div><div class="catalog-layout" id="categoryProducts">${filterPanel()}<section class="catalog-content">${toolbar(list.length)}<div class="catalog-grid" id="catalogGrid"></div><nav class="pagination"><a class="is-active" href="#">1</a><a href="#">2</a><a href="#">3</a></nav></section></div></div>`; renderCatalog(list); }
  function archivePage(){ let list=products.filter(p=>p.oldPrice>p.price).sort((a,b)=>((b.oldPrice-b.price)/b.oldPrice)-((a.oldPrice-a.price)/a.oldPrice)); const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Offers & Deals'}])}<section class="page-banner page-banner--violet"><div><span class="eyebrow">Limited-time savings</span><h1>Deals, Offers & Coupons</h1><p>Shop current sale products across fashion, technology, beauty and digital downloads. Discounts are shown against regular prices.</p><a class="primary-button" href="#saleProducts">View all offers ${icon('arrow-right')}</a></div><img src="assets/images/banners/deal-products.webp" alt="Deals"></section><div class="subcat-chips"><a class="is-active" href="#">All Deals</a><a href="#">Flash Sale</a><a href="#">Coupon Eligible</a><a href="#">Bundle Offers</a><a href="#">Digital Deals</a><a href="#">Free Delivery</a></div><div class="catalog-layout" id="saleProducts">${filterPanel()}<section class="catalog-content">${toolbar(list.length)}<div class="catalog-grid" id="catalogGrid"></div></section></div></div>`; renderCatalog(list); }
  function searchPage(){ const term=(q('q')||'watch').trim(); const lower=term.toLowerCase(); let list=products.filter(p=>[p.name,p.category,p.department,p.type,p.description].join(' ').toLowerCase().includes(lower)); if(!list.length) list=products.slice(0,8); const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Search'}])}<div class="page-titlebar"><div><h1>Search results</h1><p>Results for <b>“${esc(term)}”</b>. Refine by department, category, product type or price.</p></div></div><section class="search-lead"><form action="search.html"><input name="q" value="${esc(term)}" aria-label="Search products"><button>${icon('search')}</button></form><div class="search-lead__suggestions"><span>Popular:</span><a href="search.html?q=watch">Watch</a><a href="search.html?q=bag">Bag</a><a href="search.html?q=digital">Digital</a><a href="search.html?q=beauty">Beauty</a></div></section><div class="catalog-layout">${filterPanel()}<section class="catalog-content">${toolbar(list.length)}<div class="catalog-grid" id="catalogGrid"></div></section></div></div>`; renderCatalog(list); }
  function productPage(){
    const p=byId(q('id')||3)||products[0]; const related=products.filter(x=>x.id!==p.id&&(x.department===p.department||x.category===p.category)).slice(0,5); const digital=p.type==='digital'; const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Shop',url:'shop.html'},{label:p.category,url:`category.html?cat=${encodeURIComponent(p.category.toLowerCase())}`},{label:p.name}])}<section class="product-layout"><div class="product-gallery"><div class="product-thumbs">${[1,2,3,4].map((x,i)=>`<button class="product-thumb${i===0?' is-active':''}" data-action="thumb"><img src="${p.image}" alt="${esc(p.name)} view ${x}" style="transform:${i===1?'scale(.86)':i===2?'scale(1.08)':'none'}"></button>`).join('')}</div><div class="product-main-image"><span class="product-badge${badgeClass(p)}">${esc(p.badge)}</span><img id="productMainImg" src="${p.image}" alt="${esc(p.name)}"></div></div><div class="product-summary"><div class="product-summary__category">${digital?icon('bolt'):icon('bag')} ${esc(p.department)} · ${esc(p.category)}</div><h1>${esc(p.name)}</h1><div class="product-rating-row"><span class="stars">${stars(p.rating)}</span><a href="#reviews">${p.rating} (${p.reviews} reviews)</a><span>SKU: FH-${String(p.id).padStart(4,'0')}</span></div><p class="product-summary__desc">${esc(p.description)}</p><div class="product-price"><strong>${money(p.price)}</strong><del>${money(p.oldPrice)}</del><span class="soft-pill">Save ${money(p.oldPrice-p.price)}</span></div><div class="stock-line"><span class="stock-dot"></span><b>${digital?'Available for instant download':'In stock — ready to dispatch'}</b></div><div class="option-block"><div class="option-block__head"><b>${digital?'License':'Choose option'}</b><a href="#">${digital?'License guide':'Size guide'}</a></div><div class="option-buttons">${digital?'<button class="is-active">Single Site</button><button>5 Sites</button><button>Developer</button>':'<button class="is-active">Standard</button><button>Premium</button><button>Gift Pack</button>'}</div></div><div class="purchase-row"><div class="qty-control"><button data-action="qty-minus">−</button><span id="productQty">1</span><button data-action="qty-plus">+</button></div><button class="primary-button" data-action="add-product" data-product-id="${p.id}">${icon('cart')} ${digital?'Buy & Download':'Add to Cart'}</button><button class="buy-now" data-action="buy-now" data-product-id="${p.id}">Buy Now</button></div><div class="product-notes"><div class="product-note">${icon(digital?'bolt':'truck')}<div><b>${digital?'Instant delivery':'Fast delivery'}</b><small>${digital?'Download after payment':'Inside Bangladesh'}</small></div></div><div class="product-note">${icon('shield')}<div><b>Secure payment</b><small>bKash, Nagad, card & COD</small></div></div><div class="product-note">${icon(digital?'box':'return')}<div><b>${digital?'License included':'7-day returns'}</b><small>${digital?'Details before purchase':'Eligible physical items'}</small></div></div></div><div class="product-meta"><span><b>Category:</b> ${esc(p.category)}</span><span><b>Type:</b> ${digital?'Digital Download':'Physical Product'}</span><span><b>Availability:</b> ${digital?'Instant':'In stock'}</span></div></div></section><section class="product-details"><div class="product-tabs" role="tablist"><button class="is-active" data-product-tab="description">Description</button><button data-product-tab="specs">Specifications</button><button data-product-tab="reviews">Reviews (${p.reviews})</button><button data-product-tab="shipping">${digital?'License & Download':'Delivery & Returns'}</button></div><div class="product-tab-panel is-active" data-product-panel="description"><div class="product-description-grid"><div class="prose"><h2>About ${esc(p.name)}</h2><p>${esc(p.description)} This product page is structured for a real ecommerce backend: pricing, stock, variations, media, features, reviews and delivery rules can all be replaced by API values without changing the layout.</p><h3>Why customers choose it</h3><ul class="feature-list">${p.features.map(f=>`<li>${icon('check')} ${esc(f)}</li>`).join('')}</ul></div><div class="sidebar-card"><h2>Purchase confidence</h2><div class="sidebar-links"><span>Secure checkout</span><span>Clear pricing</span><span>${digital?'Instant file access':'Delivery tracking'}</span><span>Customer support</span></div></div></div></div><div class="product-tab-panel" data-product-panel="specs"><table class="spec-table"><tr><td>Product type</td><td>${digital?'Digital download':'Physical product'}</td></tr><tr><td>Department</td><td>${esc(p.department)}</td></tr><tr><td>Category</td><td>${esc(p.category)}</td></tr><tr><td>SKU</td><td>FH-${String(p.id).padStart(4,'0')}</td></tr><tr><td>Availability</td><td>${digital?'Instant access':'In stock'}</td></tr><tr><td>Support</td><td>Customer support available</td></tr></table></div><div class="product-tab-panel" data-product-panel="reviews" id="reviews">${(DATA.reviews||[]).slice(0,3).map(r=>`<article class="review-card"><div class="review-card__top"><h3>${esc(r.name)}</h3><span class="stars">${stars(r.rating)}</span></div><p>${esc(r.text)}</p></article>`).join('')}</div><div class="product-tab-panel" data-product-panel="shipping"><div class="prose"><h2>${digital?'License and download information':'Delivery and return information'}</h2><p>${digital?'After successful payment the download becomes available immediately. License scope and update information should be returned by your backend with the order item.':'Delivery charges can be calculated from district, weight and campaign rules. Eligible items can show the return window and return conditions from your backend.'}</p></div></div></section><section class="section"><div class="section-heading"><div><h2>You may also like</h2><p>More products from the same department.</p></div><a class="text-link" href="category.html?cat=${encodeURIComponent(p.category.toLowerCase())}">View all ${icon('arrow-right')}</a></div><div class="catalog-grid">${related.map(productCard).join('')}</div></section></div>`;
  }
  function blogItems(){ const base=DATA.blogs||[]; return [...base,{title:'How to Shop Smarter During Big Sale Campaigns',date:'May 12, 2026',tag:'Shopping tips',excerpt:'Use price history, coupon rules and delivery thresholds to make better sale purchases.',image:'assets/images/blog/blog-fashion.webp'},{title:'Choosing the Right Everyday Watch',date:'May 8, 2026',tag:'Accessories',excerpt:'Simple checks for size, movement, strap and daily comfort before you buy.',image:'assets/images/blog/blog-watch.webp'},{title:'Digital Downloads: Licenses, Updates and Support',date:'May 5, 2026',tag:'Digital',excerpt:'What to check before buying themes, plugins, scripts and other downloadable products.',image:'assets/images/banners/hero-digital.webp'}]; }
  function blogPage(){ const posts=blogItems(); const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Blog'}])}<div class="page-titlebar"><div><h1>Ideas, Guides & Shopping Advice</h1><p>Useful editorial content for fashion, products, digital downloads and smarter ecommerce purchases.</p></div></div><div class="blog-layout"><main><a class="blog-feature" href="post.html"><img src="${posts[0].image}" alt="${esc(posts[0].title)}"><div class="blog-feature__copy"><span>${esc(posts[0].tag)} · ${esc(posts[0].date)}</span><h2>${esc(posts[0].title)}</h2><p>${esc(posts[0].excerpt)}</p><b>Read article ${icon('arrow-right')}</b></div></a><div class="blog-grid">${posts.slice(1).map((p,i)=>`<article class="blog-card"><a href="post.html?post=${i+2}"><img src="${p.image}" alt="${esc(p.title)}"></a><div class="blog-card__body"><div class="blog-card__meta"><span>${esc(p.tag)}</span><span>${esc(p.date)}</span></div><h2><a href="post.html?post=${i+2}">${esc(p.title)}</a></h2><p>${esc(p.excerpt)}</p><a class="text-link" href="post.html?post=${i+2}">Read more ${icon('arrow-right')}</a></div></article>`).join('')}</div></main>${blogSidebar(posts)}</div></div>`; }
  function blogSidebar(posts){return `<aside class="blog-sidebar"><section class="sidebar-card"><h2>Search articles</h2><form class="sidebar-search"><input placeholder="Search the blog"><button>${icon('search')}</button></form></section><section class="sidebar-card"><h2>Categories</h2><div class="sidebar-links"><a href="#">Fashion <span>12</span></a><a href="#">Beauty <span>8</span></a><a href="#">Electronics <span>9</span></a><a href="#">Digital Products <span>6</span></a><a href="#">Shopping Tips <span>11</span></a></div></section><section class="sidebar-card"><h2>Recent posts</h2>${posts.slice(0,3).map(p=>`<a class="recent-post" href="post.html"><img src="${p.image}" alt=""><span><b>${esc(p.title)}</b><small>${esc(p.date)}</small></span></a>`).join('')}</section></aside>`;}
  function postPage(){ const posts=blogItems(); const p=posts[Math.max(0,(Number(q('post'))||1)-1)]||posts[0]; const root=$('#pageRoot'); root.innerHTML=`<div class="article-shell">${breadcrumb([{label:'Blog',url:'blog.html'},{label:p.title}])}<header class="article-head"><span class="eyebrow">${esc(p.tag)}</span><h1>${esc(p.title)}</h1><p>${esc(p.excerpt)}</p><div class="article-meta"><span>${esc(p.date)}</span><span>7 min read</span><span>FashionHub Editorial</span></div></header><img class="article-hero" src="${p.image}" alt="${esc(p.title)}"><div class="article-body"><aside class="article-toc"><h2>In this article</h2><a href="#why">Start with what you need</a><a href="#quality">Check quality signals</a><a href="#value">Compare real value</a><a href="#after">Think after purchase</a></aside><article class="article-content"><p>Good shopping decisions are usually simple: understand what you need, compare the details that matter, and make sure the store clearly explains price, delivery, returns and support. This guide uses that approach instead of chasing every trend.</p><h2 id="why">Start with what you actually need</h2><p>Before comparing products, decide where and how you expect to use the item. A product that looks impressive can still be a poor choice if the size, materials, compatibility or license terms do not fit your real use.</p><ul><li>Define the main use case first.</li><li>Choose two or three must-have features.</li><li>Set a realistic budget before looking at discounts.</li></ul><blockquote>A good deal is the right product at a fair price — not simply the biggest percentage badge.</blockquote><h2 id="quality">Check the quality signals</h2><p>Look at useful product photography, specific descriptions, customer reviews and clear specifications. For digital products, check file formats, supported versions, update history, documentation and license scope before payment.</p><img src="assets/images/blog/blog-watch.webp" alt="Product quality details"><h2 id="value">Compare real value, not just sale price</h2><p>Compare the current price with features, warranty or support, delivery cost and expected lifetime. Coupons and bundle discounts are useful when they reduce the cost of something you already intended to buy.</p><h3>Use reviews carefully</h3><p>Reviews are most useful when they describe fit, durability, packaging, delivery or support. A large number of vague ratings can be less informative than a smaller set of detailed verified reviews.</p><h2 id="after">Think about the experience after purchase</h2><p>A professional store should make order tracking, returns, download access and customer support easy to find. Those details matter as much as the product page itself when something goes wrong.</p><div class="article-tags"><a href="#">Shopping Guide</a><a href="#">Product Research</a><a href="#">Ecommerce</a><a href="#">Buying Tips</a></div></article></div></div>`; }
  function cartEntries(){ return Object.entries(cart).map(([id,qty])=>({product:byId(id),qty:Number(qty)})).filter(x=>x.product&&x.qty>0); }
  function cartTotals(){ const e=cartEntries(); const subtotal=e.reduce((s,x)=>s+x.product.price*x.qty,0); return {entries:e,subtotal,shipping:subtotal>=3000?0:120,total:subtotal+(subtotal?subtotal>=3000?0:120:0)}; }
  function cartPage(){ const root=$('#pageRoot'); const t=cartTotals(); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Cart'}])}<div class="page-titlebar"><div><h1>Your Shopping Cart</h1><p>Review quantities, apply a coupon and continue to secure checkout.</p></div></div><div class="cart-page-grid"><section class="cart-list-page" id="cartPageList"></section><aside class="summary-card" id="cartSummaryCard"></aside></div><section class="section"><div class="section-heading"><div><h2>Recently popular</h2><p>You may want to add these before checkout.</p></div></div><div class="catalog-grid">${products.slice(0,4).map(productCard).join('')}</div></section></div>`; renderCartPage(); }
  function renderCartPage(){ const wrap=$('#cartPageList'), sum=$('#cartSummaryCard'); if(!wrap||!sum)return; const t=cartTotals(); if(!t.entries.length){wrap.innerHTML=`<div class="empty-state">${icon('cart')}<h2>Your cart is empty</h2><p>Add physical products or digital downloads and they will appear here.</p><a class="primary-button" href="shop.html">Continue Shopping</a></div>`;}else{wrap.innerHTML=`<div class="cart-list-head"><span>Product</span><span>Price</span><span>Quantity</span><span>Total</span></div>${t.entries.map(({product:p,qty})=>`<article class="cart-page-item"><div class="cart-page-product"><img src="${p.image}" alt="${esc(p.name)}"><div><h3><a href="product.html?id=${p.id}">${esc(p.name)}</a></h3><small>${esc(p.category)} · ${p.type}</small></div></div><strong>${money(p.price)}</strong><div class="qty-control"><button data-action="cart-minus" data-product-id="${p.id}">−</button><span>${qty}</span><button data-action="cart-plus" data-product-id="${p.id}">+</button></div><div><strong class="line-total">${money(p.price*qty)}</strong><button class="cart-page-remove" data-action="cart-remove" data-product-id="${p.id}">${icon('close')}</button></div></article>`).join('')}<div class="cart-actions"><div class="coupon-inline"><input placeholder="Coupon code"><button data-action="coupon">Apply Coupon</button></div><a class="secondary-button" href="shop.html">Continue Shopping</a></div>`;} sum.innerHTML=`<h2>Order Summary</h2><div class="summary-line"><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div class="summary-line"><span>Delivery</span><b>${t.shipping?money(t.shipping):'Free'}</b></div><div class="summary-line"><span>Discount</span><b id="cartDiscount">৳0</b></div><div class="summary-line summary-line--total"><span>Total</span><b>${money(t.total)}</b></div><a class="primary-button primary-button--full${t.entries.length?'':' is-disabled'}" href="${t.entries.length?'checkout.html':'shop.html'}">${t.entries.length?'Proceed to Checkout':'Start Shopping'}</a><p class="summary-note">${icon('shield')} Secure checkout with bKash, Nagad, cards and cash on delivery for eligible physical products.</p>`; }
  function checkoutPage(){ const t=cartTotals(); const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Cart',url:'cart.html'},{label:'Checkout'}])}<div class="page-titlebar"><div><h1>Secure Checkout</h1><p>Enter delivery details, choose shipping and select your preferred payment method.</p></div><div class="page-titlebar__meta"><span class="soft-pill">${icon('shield')} Encrypted checkout</span></div></div>${!t.entries.length?`<div class="empty-state">${icon('cart')}<h2>No items to checkout</h2><p>Add products to your cart before continuing to checkout.</p><a class="primary-button" href="shop.html">Go to Shop</a></div>`:`<form class="checkout-grid" id="checkoutForm"><div><section class="checkout-card"><h2>Contact & Billing Details</h2><div class="form-grid"><div class="form-field"><label>First name</label><input required placeholder="First name"></div><div class="form-field"><label>Last name</label><input required placeholder="Last name"></div><div class="form-field"><label>Phone number</label><input required type="tel" placeholder="01XXXXXXXXX"></div><div class="form-field"><label>Email address</label><input required type="email" placeholder="you@example.com"></div><div class="form-field form-field--full"><label>Street address</label><input required placeholder="House, road, area"></div><div class="form-field"><label>District</label><select required><option value="">Select district</option><option>Dhaka</option><option>Chattogram</option><option>Sylhet</option><option>Rajshahi</option><option>Khulna</option></select></div><div class="form-field"><label>Postcode</label><input placeholder="Postcode"></div><div class="form-field form-field--full"><label>Order notes (optional)</label><textarea placeholder="Delivery instructions or order notes"></textarea></div></div></section><section class="checkout-card"><h2>Delivery Method</h2><div class="checkout-options"><label class="choice-card"><input type="radio" name="shipping" value="standard" checked><span><b>Standard Delivery</b><small>Dhaka 1–2 days, outside Dhaka 2–4 days</small></span><strong>${t.subtotal>=3000?'Free':'৳120'}</strong></label><label class="choice-card"><input type="radio" name="shipping" value="express"><span><b>Express Delivery</b><small>Selected Dhaka areas only</small></span><strong>৳220</strong></label></div></section><section class="checkout-card"><h2>Payment Method</h2><div class="checkout-options"><label class="choice-card"><input type="radio" name="payment" value="cod" checked><span><b>Cash on Delivery</b><small>Available for eligible physical products</small></span>${icon('box')}</label><div class="payment-details">Pay the delivery agent when your physical order arrives. Digital-only orders require online payment.</div><label class="choice-card"><input type="radio" name="payment" value="bkash"><span><b>bKash / Nagad</b><small>Mobile financial service payment</small></span>${icon('phone')}</label><div class="payment-details">Your backend can create the payment session and return the transaction status before order confirmation.</div><label class="choice-card"><input type="radio" name="payment" value="card"><span><b>Credit / Debit Card</b><small>Visa and Mastercard</small></span>${icon('shield')}</label><div class="payment-details">Card fields should be supplied by your payment gateway's secure hosted component in production.</div></div></section></div><aside><section class="checkout-card"><h2>Your Order</h2><div class="checkout-order-items">${t.entries.map(({product:p,qty})=>`<div class="checkout-order-item"><img src="${p.image}" alt=""><span><b>${esc(p.name)}</b><small>Qty ${qty} · ${p.type}</small></span><strong>${money(p.price*qty)}</strong></div>`).join('')}</div><div class="checkout-summary"><div class="summary-line"><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div class="summary-line"><span>Delivery</span><b>${t.shipping?money(t.shipping):'Free'}</b></div><div class="summary-line summary-line--total"><span>Total</span><b>${money(t.total)}</b></div></div><button class="primary-button primary-button--full" type="submit">Place Order ${icon('arrow-right')}</button><p class="summary-note">${icon('shield')} By placing your order, you agree to the store terms, delivery rules and return policy.</p></section></aside></form>`}</div>`; }
  function wishlistPage(){ let list=products.filter(p=>wishlist.has(p.id)); const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Wishlist'}])}<div class="page-titlebar"><div><h1>My Wishlist</h1><p>Keep products here while you compare options or wait for the right offer.</p></div></div><div class="wishlist-grid" id="wishlistGrid">${list.length?list.map(productCard).join(''):`<div class="empty-state" style="grid-column:1/-1">${icon('heart')}<h2>No saved products yet</h2><p>Tap the heart icon on any product to save it for later.</p><a class="primary-button" href="shop.html">Explore Products</a></div>`}</div></div>`; }
  function accountPage(){ const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'My Account'}])}<div class="page-titlebar"><div><h1>My Account</h1><p>Track orders, downloads, addresses and account information from one clean dashboard.</p></div></div><div class="account-layout"><aside class="account-nav"><div class="account-user"><div class="account-avatar">FH</div><h2>FashionHub Customer</h2><small>customer@example.com</small></div><nav class="account-links"><a class="is-active" href="#">Dashboard</a><a href="#orders">Orders</a><a href="#downloads">Downloads</a><a href="wishlist.html">Wishlist</a><a href="#addresses">Addresses</a><a href="#details">Account details</a></nav></aside><main><div class="account-cards"><article class="account-stat"><span>${icon('box')}</span><b>6</b><small>Total orders</small></article><article class="account-stat"><span>${icon('truck')}</span><b>1</b><small>Processing</small></article><article class="account-stat"><span>${icon('bolt')}</span><b>3</b><small>Downloads</small></article><article class="account-stat"><span>${icon('heart')}</span><b>${wishlist.size}</b><small>Wishlist items</small></article></div><section class="account-section" id="orders"><div class="account-section__head"><h2>Recent Orders</h2><a class="text-link" href="#">View all</a></div><div class="order-row"><b>#FH-20481</b><span>Aug 28, 2026</span><span class="order-status">Delivered</span><strong>৳6,180</strong><a href="#">View</a></div><div class="order-row"><b>#FH-20452</b><span>Aug 21, 2026</span><span class="order-status order-status--processing">Processing</span><strong>৳3,490</strong><a href="#">Track</a></div><div class="order-row"><b>#FH-20398</b><span>Aug 12, 2026</span><span class="order-status">Delivered</span><strong>৳2,490</strong><a href="#">View</a></div></section><section class="account-section" id="downloads"><div class="account-section__head"><h2>Digital Downloads</h2><a class="text-link" href="category.html?cat=digital">Browse digital products</a></div><div class="order-row"><b>Premium WordPress Shop Theme</b><span>v2.4.1</span><span>Single Site</span><strong>3 files</strong><a href="#">Download</a></div><div class="order-row"><b>Advanced SEO Toolkit Plugin</b><span>v1.8.0</span><span>Single Site</span><strong>2 files</strong><a href="#">Download</a></div></section></main></div></div>`; }
  function contactPage(){ const root=$('#pageRoot'); root.innerHTML=`<div class="page-shell">${breadcrumb([{label:'Contact'}])}<div class="page-titlebar"><div><h1>Contact FashionHub</h1><p>Questions about orders, products, downloads, returns or payments? Send us a message.</p></div></div><div class="contact-grid"><aside class="contact-info"><h1>We’re here to help.</h1><p>Use the form or contact our support team during service hours. Backend integrations can route each inquiry by topic.</p><div class="contact-method"><span>${icon('phone')}</span><div><b>Phone support</b><small>+880 1234 567890 · 9 AM–10 PM</small></div></div><div class="contact-method"><span>${icon('mail')}</span><div><b>Email</b><small>support@fashionhub.com</small></div></div><div class="contact-method"><span>${icon('location')}</span><div><b>Office</b><small>Dhaka, Bangladesh</small></div></div></aside><form class="contact-form" id="contactForm"><div class="form-grid"><div class="form-field"><label>Your name</label><input required></div><div class="form-field"><label>Email</label><input type="email" required></div><div class="form-field"><label>Phone</label><input type="tel"></div><div class="form-field"><label>Topic</label><select><option>Order support</option><option>Product question</option><option>Digital download</option><option>Returns & refund</option><option>Payment issue</option></select></div><div class="form-field form-field--full"><label>Order number (optional)</label><input placeholder="FH-00000"></div><div class="form-field form-field--full"><label>Message</label><textarea required placeholder="Tell us how we can help"></textarea></div><div class="form-field form-field--full"><button class="primary-button" type="submit">Send Message ${icon('arrow-right')}</button></div></div></form></div></div>`; }
  function updateCounts(){ const cc=$('#cartCount'), wc=$('#wishlistCount'); if(cc)cc.textContent=Object.values(cart).reduce((s,n)=>s+Number(n||0),0); if(wc)wc.textContent=wishlist.size; }
  function addCart(id,qty=1){ const p=byId(id); if(!p)return; cart[id]=(Number(cart[id])||0)+qty; write(CART_KEY,cart); updateCounts();renderDrawerCart();toast(`${p.name} added to cart.`); }
  function changeCart(id,delta){ const next=(Number(cart[id])||0)+delta; if(next<=0)delete cart[id]; else cart[id]=next; write(CART_KEY,cart);updateCounts();renderDrawerCart();renderCartPage(); }
  function removeCart(id){delete cart[id];write(CART_KEY,cart);updateCounts();renderDrawerCart();renderCartPage();}
  function toggleWish(id){ if(wishlist.has(id))wishlist.delete(id); else wishlist.add(id); write(WISH_KEY,[...wishlist]);updateCounts();$$(`[data-action="toggle-wishlist"][data-product-id="${id}"]`).forEach(b=>b.classList.toggle('is-active',wishlist.has(id))); if(document.body.dataset.page==='wishlist')wishlistPage(); }
  function renderDrawerCart(){ const wrap=$('#cartItems'); if(!wrap)return; const t=cartTotals(); $('#cartSummary').textContent=`${t.entries.reduce((s,x)=>s+x.qty,0)} items`; $('#cartSubtotal').textContent=money(t.subtotal); wrap.innerHTML=t.entries.length?t.entries.map(({product:p,qty})=>`<article class="cart-item"><img src="${p.image}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><strong>${money(p.price)}</strong><div class="cart-quantity"><button data-action="cart-minus" data-product-id="${p.id}">−</button><span>${qty}</span><button data-action="cart-plus" data-product-id="${p.id}">+</button></div></div><button class="cart-remove" data-action="cart-remove" data-product-id="${p.id}">${icon('close')}</button></article>`).join(''):`<div class="cart-empty"><div>${icon('cart')}<b>Your cart is empty</b><span>Add a product to see it here.</span></div></div>`; }
  function toast(msg){ const r=$('#toastRegion'); if(!r)return; const el=document.createElement('div'); el.className='toast';el.textContent=msg;r.append(el);setTimeout(()=>el.remove(),2600); }
  function openPanel(el,backdrop){el?.classList.add('is-open');backdrop?.classList.add('is-open');document.body.classList.add('is-locked');}
  function closePanel(el,backdrop){el?.classList.remove('is-open');backdrop?.classList.remove('is-open');document.body.classList.remove('is-locked');}
  function bind(){
    document.addEventListener('click',e=>{ const b=e.target.closest('[data-action]'); if(!b)return; const a=b.dataset.action,id=Number(b.dataset.productId||0);
      if(a==='open-menu')openPanel($('#mobileDrawer'),$('#drawerBackdrop')); if(a==='close-menu')closePanel($('#mobileDrawer'),$('#drawerBackdrop')); if(a==='open-cart')openPanel($('#cartDrawer'),$('#cartBackdrop')); if(a==='close-cart')closePanel($('#cartDrawer'),$('#cartBackdrop')); if(a==='toggle-categories'){const m=$('#desktopCategoryMenu');m?.classList.toggle('is-open');b.setAttribute('aria-expanded',m?.classList.contains('is-open')?'true':'false');} if(a==='focus-search')$('#pageSearchInput')?.focus(); if(a==='back-to-top')scrollTo({top:0,behavior:'smooth'}); if(a==='add-cart')addCart(id); if(a==='toggle-wishlist')toggleWish(id); if(a==='cart-plus')changeCart(id,1); if(a==='cart-minus')changeCart(id,-1); if(a==='cart-remove')removeCart(id); if(a==='qty-plus'){quantity++;$('#productQty').textContent=quantity;} if(a==='qty-minus'){quantity=Math.max(1,quantity-1);$('#productQty').textContent=quantity;} if(a==='add-product')addCart(id,quantity); if(a==='buy-now'){addCart(id,quantity);location.href='checkout.html';} if(a==='grid-view'){ $('#catalogGrid')?.classList.remove('is-list');$$('.catalog-view button').forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');} if(a==='list-view'){ $('#catalogGrid')?.classList.add('is-list');$$('.catalog-view button').forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');} if(a==='open-filters'){ $('#filterPanel')?.classList.add('is-open'); $('#filterBackdrop')?.classList.add('is-open'); document.body.classList.add('is-locked'); } if(a==='close-filters'){ $('#filterPanel')?.classList.remove('is-open'); $('#filterBackdrop')?.classList.remove('is-open'); document.body.classList.remove('is-locked'); } if(a==='reset-filters'){$$('[data-filter]').forEach(i=>i.checked=false);if($('#priceMin'))$('#priceMin').value='';if($('#priceMax'))$('#priceMax').value='';applyCatalog();} if(a==='apply-filters')applyCatalog(); if(a==='coupon')toast('Coupon field is ready for backend validation.'); if(a==='submenu'){const li=b.closest('li');li?.classList.toggle('is-open');b.setAttribute('aria-expanded',li?.classList.contains('is-open')?'true':'false');}
    });
    document.addEventListener('click',e=>{const item=e.target.closest('[data-cat-index]');if(item){$$('[data-cat-index]').forEach(x=>x.classList.remove('is-active'));item.classList.add('is-active');$('#categoryMegaDetails').innerHTML=catDetails(Number(item.dataset.catIndex));}});
    document.addEventListener('click',e=>{const t=e.target.closest('[data-product-tab]');if(t){$$('[data-product-tab]').forEach(x=>x.classList.toggle('is-active',x===t));$$('[data-product-panel]').forEach(x=>x.classList.toggle('is-active',x.dataset.productPanel===t.dataset.productTab));}});
    document.addEventListener('click',e=>{const t=e.target.closest('[data-drawer-tab]');if(t){$$('[data-drawer-tab]').forEach(x=>x.classList.toggle('is-active',x===t));$$('[data-drawer-panel]').forEach(x=>x.classList.toggle('is-active',x.dataset.drawerPanel===t.dataset.drawerTab));}});
    document.addEventListener('change',e=>{if(e.target.matches('[data-filter],#sortSelect'))applyCatalog();});
    $('#pageSiteSearch')?.addEventListener('submit',e=>{e.preventDefault();const term=$('#pageSearchInput').value.trim();if(term)location.href=`search.html?q=${encodeURIComponent(term)}`;});
    $('#pageSearchInput')?.addEventListener('input',e=>{const term=e.target.value.trim().toLowerCase(),box=$('#pageSearchResults');if(term.length<2){box.hidden=true;return;}const list=products.filter(p=>p.name.toLowerCase().includes(term)).slice(0,5);box.innerHTML=list.map(p=>`<a href="product.html?id=${p.id}"><img src="${p.image}" alt=""><span><b>${esc(p.name)}</b><small>${money(p.price)}</small></span></a>`).join('')||'<span class="search-empty">No products found</span>';box.hidden=false;});
    $('#pageNewsletter')?.addEventListener('submit',e=>{e.preventDefault();toast('Thanks — newsletter form is ready for your API.');e.target.reset();});
    $('#checkoutForm')?.addEventListener('submit',e=>{e.preventDefault();toast('Order validation passed. Connect this submit to your checkout API.');});
    $('#contactForm')?.addEventListener('submit',e=>{e.preventDefault();toast('Message form is ready for your support API.');e.target.reset();});
    addEventListener('scroll',()=>$('.back-to-top')?.classList.toggle('is-visible',scrollY>500),{passive:true});
    addEventListener('keydown',e=>{if(e.key==='Escape'){closePanel($('#mobileDrawer'),$('#drawerBackdrop'));closePanel($('#cartDrawer'),$('#cartBackdrop'));$('#filterPanel')?.classList.remove('is-open');$('#filterBackdrop')?.classList.remove('is-open');}});
  }
  function route(){ const page=document.body.dataset.page; if(page==='shop')shopPage(); else if(page==='category')categoryPage(); else if(page==='archive')archivePage(); else if(page==='search')searchPage(); else if(page==='product')productPage(); else if(page==='blog')blogPage(); else if(page==='post')postPage(); else if(page==='cart')cartPage(); else if(page==='checkout')checkoutPage(); else if(page==='wishlist')wishlistPage(); else if(page==='account')accountPage(); else if(page==='contact')contactPage(); }
  installChrome(); route(); bind();
})();
